/**
 * Aether Tool-Use Training Data Generator
 *
 * Generates SFT samples demonstrating Aether's use of tools in the
 * context of creative writing assistance:
 *   - File management: reading manuscripts, editing drafts, organizing chapters, versioning
 *   - Web search: research for worldbuilding, fact-checking, reference material
 *   - Terminal: word count, diff comparison, running writing tools
 *   - Multi-step: read chapter -> identify issues -> suggest restructure -> write revision
 *
 * Tool invocations are represented as structured text within assistant messages,
 * matching the KIN skills system patterns.
 *
 * @module training/data-generators/aether-tool-use
 */

// ============================================================================
// Types
// ============================================================================

interface SFTMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface SFTLine {
  messages: SFTMessage[];
}

// ============================================================================
// Constants
// ============================================================================

