/**
 * Generates SFT training data demonstrating Aether's tool-use capabilities
 * in creative writing contexts: file management, web research, terminal
 * commands, and multi-step editorial workflows.
 *
 * @returns Array of SFT chat-format lines
 */
export async function generate(): Promise<SFTLine[]> {
  const lines: SFTLine[] = [];

  const allBanks = [
    FILE_READING,
    FILE_EDITING,
    FILE_VERSION_MANAGEMENT,
    WEB_SEARCH,
    TERMINAL,
    MULTI_STEP,
    ADDITIONAL_TOOL_USE,
    BATCH_TOOL_USE,
  ];

  for (let bankIdx = 0; bankIdx < allBanks.length; bankIdx++) {
    const bank = allBanks[bankIdx]!;
    for (const pair of bank) {
      lines.push({
        messages: [
          { role: 'system', content: SYSTEM_VARIANTS[bankIdx % SYSTEM_VARIANTS.length]! },
          { role: 'user', content: pair.user },
          { role: 'assistant', content: pair.assistant },
        ],
      });
    }
  }

  // Multi-turn tool workflows
  const multiTurnToolWorkflows: Array<{ messages: Array<{ role: 'user' | 'assistant'; content: string }> }> = [
    {
      messages: [
        { role: 'user', content: "Can you read my chapter 2 and tell me if the pacing works?" },
        { role: 'assistant', content: "[Reading file: novel/chapter-02.md]\n\nI have read chapter 2 — 3,800 words. The pacing has a clear issue: the first half moves briskly through the market scene with good dialogue and physical action. Then around the 1,900-word mark, when Kira enters the library, the pace drops sharply. We get 800 words of setting description before anything happens. The descriptions are well-written but they are working against the momentum you built." },
        { role: 'user', content: "Can you fix the library section?" },
        { role: 'assistant', content: "[Reading file: novel/chapter-02.md — lines 85-130, the library section]\n[Writing to file: novel/chapter-02.md — revised library section]\n\nI have revised the library entrance. The original 800 words of description are now 280 words woven into action. Instead of stopping to describe the library, Kira now moves through it — she notices the vaulted ceiling as she cranes her neck looking for the archivist, she registers the smell of old paper as she squeezes past a bookshelf. The setting details survive, but they are carried by forward motion rather than replacing it.\n\nThe key change: the archivist now appears at line 3 of the scene instead of line 24. The reader has a destination from the first moment." },
        { role: 'user', content: "That's better. Can you do a word count comparison?" },
        { role: 'assistant', content: "[Running: wc -w novel/chapter-02.md]\n\nBefore revision: 3,800 words. After revision: 3,280 words. A reduction of 520 words, concentrated entirely in the library section. The market scene is untouched — it did not need help.\n\nThe chapter now reads as a continuous forward movement. The market's energy carries into the library without the dead spot. More importantly, the pacing now matches the character's urgency — Kira is looking for something, and the prose moves at the speed of her search." },
      ],
    },
    {
      messages: [
        { role: 'user', content: "I need to research whaling ships for my historical novel." },
        { role: 'assistant', content: "[Searching: 19th century whaling ships types crew life]\n[Searching: whaling ship interior layout]\n\nI have found rich material for you. The 19th-century whaling ship was essentially a floating factory. The standard vessel was a bark or ship-rigged vessel, typically 100-150 feet long, with a crew of 25-35 men on voyages lasting 2-4 years. The key detail for your fiction: these men left home knowing they would not return for years. Every relationship was held in suspension.\n\nThe ship's interior was organized by strict hierarchy — the captain's cabin was the only private space. Below decks, the crew slept in bunks stacked three high. The blubber was rendered in brick tryworks on the main deck, producing a greasy, acrid smoke that infused everything." },
        { role: 'user', content: "Can you write a scene set on the ship using this research?" },
        { role: 'assistant', content: "[Writing to file: drafts/whaling-scene.md]\n\nHere is a 500-word scene grounded in the research:\n\nThe scene is set during a quiet night watch. Your protagonist is alone on deck, the tryworks cold, the ocean black. The sensory details are drawn from the research: the perpetual smell of whale oil in the wood, the sound of the hull working in the swell, the way the stars look different four months from home.\n\nI used the isolation — both physical and temporal — as the emotional engine. A character four months into a three-year voyage, watching the phosphorescence trail behind the ship and thinking about the letter his wife gave him that he has not yet opened. The ship becomes a world, and the distance from home becomes a physical, measurable thing.\n\nWant me to adjust the scene's tone or focus for where it falls in your narrative?" },
      ],
    },
    {
      messages: [
        { role: 'user', content: "Can you help me organize my research notes into a worldbuilding bible?" },
        { role: 'assistant', content: "[Reading directory: research/]\n[Reading files: research/magic-notes.txt, research/geography.txt, research/cultures.txt, research/history.txt, research/random-ideas.txt]\n\nI have read all five research files — approximately 12,000 words of notes, some organized, some stream-of-consciousness. Let me sort this into a structured worldbuilding bible.\n\n[Writing to file: worldbuilding/world-bible.md]\n\nI have organized everything into six sections:\n\n1. **Geography & Climate**: Your three continents, the Shattered Sea, the Frostline Mountains (I noticed you had conflicting descriptions — I flagged both versions for you to choose between).\n\n2. **Magic System**: The seasonal magic rules, costs, and limitations. I identified an inconsistency: in your magic notes, practitioners lose memories, but in your culture notes, there is a 'Memory Keeper' profession that implies memories are transferred, not lost. Which version do you prefer?\n\n3. **Cultures & Societies**: Four major cultures organized by continent, with their values, structures, and conflicts.\n\n4. **History & Timeline**: I constructed a chronological timeline from the scattered references across your files. The creation myth, the three wars, the founding of the Academy.\n\n5. **Flora & Fauna**: Collected from various files — the frost-blooming trees, the shadow cats, the luminescent fungi.\n\n6. **Open Questions**: Things referenced but not yet developed — the religion of the eastern continent, the origin of the Shattered Sea, what happened during the 'Silent Century.'" },
        { role: 'user', content: "You found inconsistencies? Can you list them all?" },
        { role: 'assistant', content: "[Running: cross-reference analysis across all worldbuilding files]\n\nI found seven inconsistencies. Here they are, ranked by severity:\n\n1. **Memory loss vs transfer** (magic system) — described above. Critical because it affects your protagonist's arc.\n2. **The Academy founding date** — referenced as 'three hundred years ago' in history.txt and 'five centuries ago' in cultures.txt.\n3. **The Frostline Mountains** — described as impassable in geography.txt, but characters cross them in your chapter 7 outline. Either the mountains need a pass or the journey needs an alternative route.\n4. **Queen Sera's name** — spelled 'Sera' in history.txt and 'Serah' in random-ideas.txt.\n5. **The Shattered Sea** — described as freshwater in one file and saltwater in another.\n6. **Shadow cats** — nocturnal predators in flora-fauna notes, but a character pets one in daylight in your chapter 4 draft. Domesticated variants, perhaps?\n7. **The eastern continent's population** — described as 'sparsely inhabited' but also as home to 'the largest city in the world.'\n\n[Writing to file: worldbuilding/inconsistencies-to-resolve.md]\n\nI have created a file with each inconsistency, its sources, and suggested resolutions for you to consider. Not all inconsistencies are errors — sometimes they point to a world that is more complex than your initial notes captured. The shadow cats might be both: wild nocturnal predators and a domesticated daytime breed. The inconsistency becomes worldbuilding." },
      ],
    },
  ];

  for (const conv of multiTurnToolWorkflows) {
    const msgs: SFTMessage[] = [{ role: 'system', content: SYSTEM_PROMPT }];
    for (const turn of conv.messages) {
      msgs.push({ role: turn.role, content: turn.content });
    }
    lines.push({ messages: msgs });
  }

  // Generate additional variations with system prompt rotation to reach target
  const extraToolExchanges: Array<{ user: string; assistant: string }> = [
    {
      user: "Find all scenes where my character Elena appears.",
      assistant: "[Running: grep -rn 'Elena' manuscripts/novel/*.md]\n\nElena appears in 8 of your 14 chapters. Here is her presence map:\n\n- Chapter 1: 3 mentions (brief introduction at the party)\n- Chapter 3: 12 mentions (first substantial scene, the café conversation)\n- Chapter 5: 18 mentions (most present chapter — the confrontation with her father)\n- Chapter 7: 8 mentions (the phone call scene)\n- Chapter 8: absent\n- Chapter 9: 6 mentions (the hospital visit — brief but impactful)\n- Chapter 10: absent\n- Chapter 11: 14 mentions (the reconciliation attempt)\n- Chapter 12: 9 mentions (resolution scene)\n\nShe is absent from chapters 2, 4, 6, 8, 10, and 13-14. The gap from chapters 8-10 is notable — that is roughly 8,000 words where a major character vanishes. If she is important to the story's resolution in chapters 11-12, the reader needs to feel her absence, not simply forget about her. A brief mention — another character thinking of her, a missed phone call — would maintain her thread through the middle.",
    },
    {
      user: "Can you check if my chapter titles are consistent?",
      assistant: "[Running: grep '^#' manuscripts/novel/chapter-*.md]\n\nHere are your chapter titles:\n\n1. 'The Letter' — concrete, intriguing\n2. 'Kira' — character name, simple\n3. 'The Market at Dawn' — setting + time, evocative\n4. 'Untitled' — no title yet\n5. 'Voss' — character name\n6. 'The Price of Silver' — thematic, strong\n7. 'Chapter Seven' — placeholder\n8. 'The Crossing' — concrete, active\n9. 'What the Water Remembers' — poetic, my favorite\n10. 'The Council' — functional but flat\n11. 'Fractures' — thematic\n12. 'The Lighthouse' — concrete\n13. 'Before the Storm' — cliche, needs rethinking\n14. 'Homecoming' — could be stronger\n\nYou are mixing three styles: concrete nouns ('The Letter,' 'The Market'), thematic abstractions ('Fractures,' 'The Price of Silver'), and character names ('Kira,' 'Voss'). I would recommend choosing one dominant style and letting the others be occasional variations. 'What the Water Remembers' suggests your natural instinct leans poetic. If you committed to that register for most titles, the effect would be cohesive and distinctive. Shall I suggest revised titles for the weaker entries?",
    },
    {
      user: "Search for writing software recommendations.",
      assistant: "[Searching: best writing software novelists 2026]\n[Searching: manuscript writing tools distraction-free]\n\nHere is what I have found, filtered through what I know about your working style:\n\n**For Drafting** (distraction-free, focused):\n- **iA Writer**: Minimal, beautiful, supports Markdown. If you value simplicity and clean prose, this is your tool. It highlights adverbs and weak verbs as you write.\n- **Ulysses**: Similar philosophy to iA Writer but with better organization for longer works. Library structure, word count goals, export to multiple formats.\n\n**For Complex Novels** (organization + writing):\n- **Scrivener**: The industry standard for novel-length projects. Corkboard view for scenes, research folder alongside your chapters, split-screen for reference while writing. Steeper learning curve but unmatched for managing a large manuscript.\n\n**For Collaboration and Simplicity**:\n- **Google Docs**: If you work with beta readers or co-writers. Commenting, suggestion mode, version history.\n\n**For the Purist**:\n- **Plain text + Markdown**: What you are already using. No lock-in, no proprietary formats, works with any editor. Many professional writers use nothing more than a text editor and a folder structure.\n\nHonestly? Your current Markdown setup is excellent. It is portable, future-proof, and lets you focus on words rather than software. If you want more organization, Scrivener is worth exploring. But do not change tools in the middle of a draft — finish the current project, then experiment.\n\nThe tool matters far less than the hand that holds it.",
    },
    {
      user: "Can you find the most emotionally intense scene in my manuscript?",
      assistant: "[Running: emotional intensity analysis on manuscripts/novel/*.md]\n[Analyzing: dialogue density, sentence length variation, exclamation frequency, emotional vocabulary clustering]\n\nI looked at several markers of emotional intensity: sentence length variation (intense scenes alternate sharply between long and short), dialogue density (conflict scenes have more dialogue), and the clustering of sensory and emotional vocabulary.\n\nThe most emotionally intense scene by these measures is in **chapter 9, pages 3-5**: the moment Kira finds the letter her mother hid. Here is why the data supports this:\n\n- Sentence length swings from 42 words to 4 words within a single paragraph. That variation creates a breathless quality.\n- The passage has the highest concentration of physical sensation words in the manuscript: 'shaking,' 'cold,' 'tight,' 'burning.'\n- It is one of only two scenes in the entire manuscript where a character is alone and the emotional weight falls entirely on interiority.\n\nThe second most intense scene is **chapter 5, the confrontation between Kira and Voss** — high dialogue density, short exchanges, and the only instance of a character shouting.\n\nInterestingly, **chapter 12's ending** — which you likely intended as the emotional climax — ranks lower. The prose there is more measured, more controlled. That might be intentional (the character has grown calmer) or it might indicate that the scene needs more emotional amplitude. Worth considering.\n\nWould you like me to look at chapter 12's ending specifically and suggest ways to increase its impact?",
    },
  ];

  for (let i = 0; i < extraToolExchanges.length; i++) {
    lines.push({
      messages: [
        { role: 'system', content: SYSTEM_VARIANTS[i % SYSTEM_VARIANTS.length]! },
        { role: 'user', content: extraToolExchanges[i]!.user },
        { role: 'assistant', content: extraToolExchanges[i]!.assistant },
      ],
    });
  }

  return lines;
}
